BEGIN;
CREATE TABLE knowledge_safety_assessment(tenant_id uuid NOT NULL,workspace_id uuid NOT NULL,assessment_id text NOT NULL CHECK(assessment_id~'^[a-f0-9]{64}$'),source_id uuid NOT NULL,asset_id uuid NOT NULL,version_id uuid NOT NULL,owner_id uuid NOT NULL,normalized_checksum text NOT NULL CHECK(normalized_checksum~'^sha256:[a-f0-9]{64}$'),classification text NOT NULL,policy_version text NOT NULL,scanner_profile text NOT NULL,scanner_version text NOT NULL,trust_origin text NOT NULL CHECK(trust_origin='untrusted_external_data'),score numeric(4,3) NOT NULL CHECK(score BETWEEN 0 AND 1),decision text NOT NULL CHECK(decision IN('allow_with_markers','review_required','quarantine','block')),findings jsonb NOT NULL CHECK(jsonb_typeof(findings)='array'AND jsonb_array_length(findings)<=100),assessed_at timestamptz NOT NULL,version bigint NOT NULL DEFAULT 1 CHECK(version>0),reviewed_by uuid,reviewed_at timestamptz,review_reason_hash text CHECK(review_reason_hash~'^sha256:[a-f0-9]{64}$'),PRIMARY KEY(tenant_id,workspace_id,assessment_id),FOREIGN KEY(tenant_id,workspace_id,asset_id,version_id)REFERENCES knowledge_version_governance(tenant_id,workspace_id,asset_id,version_id)ON DELETE RESTRICT,UNIQUE(tenant_id,workspace_id,version_id,normalized_checksum,scanner_profile,scanner_version));
CREATE TABLE knowledge_safety_outbox(tenant_id uuid NOT NULL,workspace_id uuid NOT NULL,event_id uuid NOT NULL,event_type text NOT NULL CHECK(event_type IN('knowledge.safety.assessed.v1','knowledge.safety.review_required.v1','knowledge.safety.quarantined.v1','knowledge.safety.released.v1','knowledge.safety.rejected.v1','knowledge.safety.blocked.v1')),request_id uuid NOT NULL,assessment_id text NOT NULL,asset_id uuid NOT NULL,version_id uuid NOT NULL,normalized_checksum text NOT NULL,scanner_version text NOT NULL,decision text NOT NULL,assessment_version bigint NOT NULL,occurred_at timestamptz NOT NULL,published_at timestamptz,PRIMARY KEY(tenant_id,workspace_id,event_id),FOREIGN KEY(tenant_id,workspace_id,assessment_id)REFERENCES knowledge_safety_assessment(tenant_id,workspace_id,assessment_id)ON DELETE RESTRICT);
REVOKE ALL ON knowledge_safety_assessment,knowledge_safety_outbox FROM PUBLIC;GRANT SELECT,INSERT,UPDATE(decision,version,reviewed_by,reviewed_at,review_reason_hash)ON knowledge_safety_assessment TO domus_knowledge_runtime;GRANT SELECT,INSERT ON knowledge_safety_outbox TO domus_knowledge_runtime;
ALTER TABLE knowledge_safety_assessment ENABLE ROW LEVEL SECURITY;ALTER TABLE knowledge_safety_assessment FORCE ROW LEVEL SECURITY;ALTER TABLE knowledge_safety_outbox ENABLE ROW LEVEL SECURITY;ALTER TABLE knowledge_safety_outbox FORCE ROW LEVEL SECURITY;
CREATE POLICY knowledge_safety_assessment_scope ON knowledge_safety_assessment TO domus_knowledge_runtime USING(tenant_id=domus_security.current_uuid('app.current_tenant_id')AND workspace_id=domus_security.current_uuid('app.current_workspace_id'))WITH CHECK(tenant_id=domus_security.current_uuid('app.current_tenant_id')AND workspace_id=domus_security.current_uuid('app.current_workspace_id'));CREATE POLICY knowledge_safety_outbox_scope ON knowledge_safety_outbox TO domus_knowledge_runtime USING(tenant_id=domus_security.current_uuid('app.current_tenant_id')AND workspace_id=domus_security.current_uuid('app.current_workspace_id'))WITH CHECK(tenant_id=domus_security.current_uuid('app.current_tenant_id')AND workspace_id=domus_security.current_uuid('app.current_workspace_id'));
INSERT INTO schema_migrations(version,description)VALUES(16,'V1-406 indirect instruction injection content safety')ON CONFLICT(version)DO NOTHING;COMMIT;
